from pathlib import Path
import re

page = Path('app/page.tsx')
s = page.read_text()

new_modal = r'''function EventModal({clients,event,onClose,onSaved}:any){const allowedStatuses=['preventivo_inviato','confermato','annullato'];const initialStatus=allowedStatuses.includes(event?.status)?event.status:'preventivo_inviato';const [form,setForm]=useState({client_id:event?.client_id||'',event_date:event?.event_date||new Date().toISOString().slice(0,10),service:event?.service||'cena',adults:event?.adults??0,baby:event?.baby??0,status:initialStatus,price_per_adult:event?.price_per_adult??'',price_per_baby:event?.price_per_baby??'',internal_notes:event?.internal_notes||''});const [saving,setSaving]=useState(false);async function save(e:FormEvent){e.preventDefault();if(!supabase)return;setSaving(true);const payload={client_id:form.client_id||null,event_date:form.event_date,service:form.service,adults:Number(form.adults),baby:Number(form.baby),status:form.status,price_per_adult:form.price_per_adult===''?null:Number(form.price_per_adult),price_per_baby:form.price_per_baby===''?null:Number(form.price_per_baby),internal_notes:form.internal_notes};const res=event?await supabase.from('events').update(payload).eq('id',event.id):await supabase.from('events').insert(payload);setSaving(false);if(!res.error){await onSaved();onClose()}else alert(res.error.message)}return <Modal title={event?`Evento #${event.event_number}`:'Nuovo evento'} onClose={onClose} wide><form onSubmit={save} className="formGrid eventForm"><label className="eventClientField">Cliente<select value={form.client_id} onChange={e=>setForm({...form,client_id:e.target.value})}><option value="">Seleziona cliente</option>{clients.map((c:Client)=><option key={c.id} value={c.id}>{nameOfClient(c)}</option>)}</select></label><div className="eventTopRow"><label>Data<input type="date" value={form.event_date} onChange={e=>setForm({...form,event_date:e.target.value})} required/></label><label>Servizio<select value={form.service} onChange={e=>setForm({...form,service:e.target.value})}><option value="pranzo">Pranzo</option><option value="cena">Cena</option><option value="altro">Altro</option></select></label><label>Stato<select value={form.status} onChange={e=>setForm({...form,status:e.target.value})}><option value="preventivo_inviato">Preventivo inviato</option><option value="confermato">Confermato</option><option value="annullato">Annullato</option></select></label></div><div className="eventPairRow"><label>Adulti<input type="number" min="0" value={form.adults} onChange={e=>setForm({...form,adults:e.target.value as any})}/></label><label>Baby<input type="number" min="0" value={form.baby} onChange={e=>setForm({...form,baby:e.target.value as any})}/></label></div><div className="eventPairRow"><label>Prezzo per persona €<input type="number" step="0.01" min="0" value={form.price_per_adult} onChange={e=>setForm({...form,price_per_adult:e.target.value as any})}/></label><label>Prezzo menu baby €<input type="number" step="0.01" min="0" value={form.price_per_baby} onChange={e=>setForm({...form,price_per_baby:e.target.value as any})}/></label></div><label className="span2">Note interne<textarea rows={4} value={form.internal_notes} onChange={e=>setForm({...form,internal_notes:e.target.value})}/></label><div className="formActions span2"><button type="button" className="ghost" onClick={onClose}>Annulla</button><button className="primary" disabled={saving}>{saving?'Salvataggio…':'Salva evento'}</button></div></form></Modal>}'''

s, n = re.subn(r'function EventModal\(\{clients,event,onClose,onSaved\}:any\).*?(?=function ClientModal)', new_modal + '\n', s, count=1, flags=re.S)
if n != 1:
    raise SystemExit('EventModal non trovato o sostituzione ambigua')
page.write_text(s)
